import 'package:flutter/material.dart';
import 'package:provider/provider.dart';
import 'package:url_launcher/url_launcher.dart';
import '../core/constants.dart';
import '../models/media_item.dart';
import '../providers/media_provider.dart';
import '../providers/ai_provider.dart';
class DetailScreen extends StatefulWidget{final MediaItem item;const DetailScreen({super.key,required this.item});@override State<DetailScreen> createState()=>_DetailScreenState();}
class _DetailScreenState extends State<DetailScreen>{late MediaItem item;bool loading=false;@override void initState(){super.initState();item=widget.item;_load();}Future<void> _load()async{final x=await context.read<MediaProvider>().details(item,'ar');if(mounted)setState(()=>item=x);}Future<void> _status(String s)async{await context.read<MediaProvider>().setStatus(item,s);setState(()=>item=item.copyWith(watchStatus:s));}Future<void> _note()async{final c=TextEditingController(text:item.notes);final ok=await showDialog<bool>(context:context,builder:(_)=>AlertDialog(title:const Text('ملاحظتي'),content:TextField(controller:c,maxLines:5),actions:[TextButton(onPressed:()=>Navigator.pop(context),child:const Text('إلغاء')),ElevatedButton(onPressed:()=>Navigator.pop(context,true),child:const Text('حفظ'))]));if(ok==true){await context.read<MediaProvider>().setNotes(item,c.text);setState(()=>item=item.copyWith(notes:c.text));}}Future<void> _ai()async{setState(()=>loading=true);try{final x=await context.read<AiProvider>().summarize(item);if(mounted)showDialog(context:context,builder:(_)=>AlertDialog(title:const Text('ملخص AI'),content:SingleChildScrollView(child:Text(x.summary)),actions:[TextButton(onPressed:()=>Navigator.pop(context),child:const Text('إغلاق'))]));}catch(e){if(mounted)ScaffoldMessenger.of(context).showSnackBar(SnackBar(content:Text(e.toString())));}finally{if(mounted)setState(()=>loading=false);}}@override Widget build(BuildContext context){return Scaffold(body:CustomScrollView(slivers:[SliverAppBar(expandedHeight:280,pinned:true,flexibleSpace:FlexibleSpaceBar(title:Text(item.title,maxLines:1,overflow:TextOverflow.ellipsis),background:item.backdropUrl==null?Container(color:Theme.of(context).colorScheme.surfaceContainerHighest):Image.network(item.backdropUrl!,fit:BoxFit.cover))),SliverToBoxAdapter(child:Padding(padding:const EdgeInsets.all(16),child:Column(crossAxisAlignment:CrossAxisAlignment.start,children:[Row(children:[_statusButton('تمت',AppConstants.statusWatched),_statusButton('أشاهد',AppConstants.statusWatching),_statusButton('قائمة',AppConstants.statusNotWatched)]),const SizedBox(height:16),Text(item.overview.isEmpty?'لا يوجد وصف متاح':item.overview),const SizedBox(height:16),Wrap(spacing:8,children:item.genres.map((g)=>Chip(label:Text(g))).toList()),const SizedBox(height:12),Text('التقييم العالمي: '+item.voteAverage.toStringAsFixed(1)),if(item.cast.isNotEmpty)Text('الطاقم: '+item.cast.take(8).join('، ')),if(item.director!=null)Text('المخرج: '+item.director!),const SizedBox(height:16),Wrap(spacing:8,children:[ElevatedButton.icon(onPressed:_note,icon:const Icon(Icons.note_add),label:const Text('ملاحظة')),ElevatedButton.icon(onPressed:loading?null:_ai,icon:const Icon(Icons.auto_awesome),label:const Text('تحليل AI')),if(item.trailerKey!=null)IconButton(onPressed:()=>launchUrl(Uri.parse('https://www.youtube.com/watch?v='+item.trailerKey!)),icon:const Icon(Icons.play_circle))])])))]));}Widget _statusButton(String l,String s)=>Expanded(child:Padding(padding:const EdgeInsets.only(right:4),child:OutlinedButton(onPressed:()=>_status(s),child:Text(l))));}
